import jwt from 'jsonwebtoken';

const RAHASIA = 'kunci-rahasia-yang-panjang-dan-acak';
const token = jwt.sign({ sub: '7', peran: 'kasir' }, RAHASIA, { expiresIn: '15m' });
const [header, payload] = token.split('.');

console.log(token.split('.').length);
console.log(JSON.parse(Buffer.from(header, 'base64url').toString()));
const isi = JSON.parse(Buffer.from(payload, 'base64url').toString());
console.log(isi.sub, isi.peran, isi.exp - isi.iat);

const palsu = [header, Buffer.from(JSON.stringify({ ...isi, peran: 'admin' })).toString('base64url'), token.split('.')[2]].join('.');
for (const [nama, t, kunci] of [['asli', token, RAHASIA], ['payload diubah', palsu, RAHASIA], ['kunci salah', token, 'tebakan']]) {
  try {
    console.log(nama, '->', jwt.verify(t, kunci).peran);
  } catch (e) {
    console.log(nama, '->', e.message);
  }
}

